import sys
import heapq

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    edges_info = []

    for i in range(1, m + 1):
        u_edge = int(next(iterator))
        v_edge = int(next(iterator))
        w_edge = int(next(iterator))

        adj[u_edge].append((v_edge, w_edge, i))
        adj[v_edge].append((u_edge, w_edge, i))
        edges_info.append((u_edge, v_edge, w_edge, i))

    start_node = int(next(iterator))

    dist = [-1] * (n + 1)
    parent_edge_idx = [0] * (n + 1)

    pq = [(0, start_node)]
    dist[start_node] = 0

    while pq:
        d, u = heapq.heappop(pq)

        if dist[u] != -1 and d > dist[u]:
            continue

        for v, w, idx in adj[u]:
            new_dist = d + w

            if dist[v] == -1 or new_dist < dist[v]:
                dist[v] = new_dist
                parent_edge_idx[v] = idx
                heapq.heappush(pq, (new_dist, v))
            elif new_dist == dist[v]:
                if w < dist[v] - dist[u]:
                    pass
                else:
                    if parent_edge_idx[v] == 0 or (dist[v] - dist[u] == w and w < dist[v] - dist[u]):
                        pass
                    if w < (dist[v] - dist[u]) or (w == (dist[v] - dist[u]) and idx < parent_edge_idx[v]):
                        if parent_edge_idx[v] == 0:
                            parent_edge_idx[v] = idx
                        else:
                            current_w = 0
                            for x, y, z, k in edges_info:
                                if k == parent_edge_idx[v]:
                                    current_w = z
                                    break
                            if w < current_w:
                                parent_edge_idx[v] = idx
                            elif w == current_w and idx < parent_edge_idx[v]:
                                parent_edge_idx[v] = idx

    selected_edges = []
    total_weight = 0

    for i in range(1, n + 1):
        if i != start_node:
            idx = parent_edge_idx[i]
            if idx != 0:
                selected_edges.append(idx)
                for u_e, v_e, w_e, k in edges_info:
                    if k == idx:
                        total_weight += w_e
                        break

    print(total_weight)
    print(*(selected_edges))

if __name__ == "__main__":
    main()
